/**
 * UserPanel Preloader Management
 * Handles showing/hiding the preloader on the right side of the panel
 */

class UserPanelPreloader {
    constructor() {
        this.preloader = null;
        this.init();
    }

    init() {
        this.preloader = document.getElementById('preloader');
        this.bindEvents();
        this.hideOnPageLoad();
    }

    bindEvents() {
        // Hide preloader after page loads
        document.addEventListener('DOMContentLoaded', () => {
            this.hideOnPageLoad();
        });

        // Show preloader on navigation
        window.addEventListener('beforeunload', () => {
            this.show();
        });

        // Show preloader on AJAX requests
        document.addEventListener('ajax:start', () => {
            this.show();
        });

        document.addEventListener('ajax:end', () => {
            this.hide();
        });

        // Intercept fetch requests to show preloader
        this.interceptFetch();
    }

    hideOnPageLoad() {
        if (this.preloader) {
            setTimeout(() => {
                this.hide();
                // Remove from DOM after animation
                setTimeout(() => {
                    if (this.preloader && this.preloader.parentNode) {
                        this.preloader.parentNode.removeChild(this.preloader);
                    }
                }, 300);
            }, 500);
        }
    }

    show() {
        if (this.preloader) {
            this.preloader.classList.remove('hidden');
        }
    }

    hide() {
        if (this.preloader) {
            setTimeout(() => {
                this.preloader.classList.add('hidden');
            }, 300);
        }
    }

    interceptFetch() {
        const originalFetch = window.fetch;
        let activeRequests = 0;

        window.fetch = (...args) => {
            activeRequests++;
            this.show();

            return originalFetch(...args)
                .finally(() => {
                    activeRequests--;
                    if (activeRequests === 0) {
                        this.hide();
                    }
                });
        };
    }
}

// Initialize preloader when DOM is ready
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        new UserPanelPreloader();
    });
} else {
    new UserPanelPreloader();
}

// Global functions for manual control
window.showUserPanelPreloader = function() {
    const preloader = document.getElementById('preloader');
    if (preloader) {
        preloader.classList.remove('hidden');
    }
};

window.hideUserPanelPreloader = function() {
    const preloader = document.getElementById('preloader');
    if (preloader) {
        setTimeout(() => {
            preloader.classList.add('hidden');
        }, 300);
    }
};

// Export for module usage
if (typeof module !== 'undefined' && module.exports) {
    module.exports = UserPanelPreloader;
}
